(5056739, 737666, 54446, '<td valign="top">Wonderful narrow DOF.  Interesting image to view.  Something not often seen.  Great entry for this challenge.  (9)</td>', 'Wonderful narrow DOF.  Interesting image to view.  Something not often seen.  Great entry for this challenge.  (9)', '2008-11-11 11:06:40.000000', NULL, 1),
(5056742, 737809, 54446, '<td valign="top">Very nice still life and historical image.  Good entry for this challenge.  Clearly says "Lead".  (8)</td>', 'Very nice still life and historical image.  Good entry for this challenge.  Clearly says "Lead".  (8)', '2008-11-11 11:07:49.000000', NULL, 1),
(5056746, 737819, 54446, '<td valign="top">Very nice diffraction of light through the bulb.  Effective use of differential tones!  Great idea, well executed.  (8)</td>', 'Very nice diffraction of light through the bulb.  Effective use of differential tones!  Great idea, well executed.  (8)', '2008-11-11 11:09:11.000000', NULL, 1),
(5056747, 737925, 30982, '<td valign="top">Carbon?  :-)  Love the glow of the pump.</td>', 'Carbon?  :-)  Love the glow of the pump.', '2008-11-11 11:09:47.000000', NULL, 1),
