(5056803, 737844, 30982, '<td valign="top">Very pretty piece, both the bowl and the picture.  I like the bluish at the bottom - very complimentary for copper.</td>', 'Very pretty piece, both the bowl and the picture.  I like the bluish at the bottom - very complimentary for copper.', '2008-11-11 11:27:30.000000', NULL, 1),
(5056805, 737876, 30982, '<td valign="top">Very nice portrait, nice interpretation of the challenge.</td>', 'Very nice portrait, nice interpretation of the challenge.', '2008-11-11 11:27:52.000000', NULL, 1),
