(5056819, 737516, 76598, '<td valign="top">In general images of other art does not appeal to me.</td>', 'In general images of other art does not appeal to me.', '2008-11-11 11:34:41.000000', NULL, 1),
(5056821, 737666, 76598, '<td valign="top">Very interesting, you have turned rust into a landscape, good color, good composition and use of depth of field.</td>', 'Very interesting, you have turned rust into a landscape, good color, good composition and use of depth of field.', '2008-11-11 11:35:26.000000', NULL, 1),
