INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5057282, 737914, 53316, '<td valign="top">This is what I wish my entry had been. Good job.</td>', 'This is what I wish my entry had been. Good job.', '2008-11-11 15:28:08.000000', NULL, 1),
(5057292, 737814, 53316, '<td valign="top">Oh how fantastic! Such a great idea.</td>', 'Oh how fantastic! Such a great idea.', '2008-11-11 15:31:48.000000', NULL, 1),
(5057301, 737929, 64670, '<td valign="top">Wonderful, stunning, delicious &amp; gorgeous!</td>', 'Wonderful, stunning, delicious & gorgeous!', '2008-11-11 15:33:19.000000', NULL, 1),
(5057312, 737375, 64670, '<td valign="top">WONDERFUL play on words and the image is BRILLIANT!</td>', 'WONDERFUL play on words and the image is BRILLIANT!', '2008-11-11 15:37:45.000000', NULL, 1),
(5057314, 737858, 43774, '<td valign="top">How creative!!</td>', 'How creative!!', '2008-11-11 15:38:19.000000', NULL, 1),
(5057315, 737876, 43774, '<td valign="top">I really like this.</td>', 'I really like this.', '2008-11-11 15:38:26.000000', NULL, 1),
(5057316, 737919, 43774, '<td valign="top">LOL this is funny.</td>', 'LOL this is funny.', '2008-11-11 15:38:31.000000', NULL, 1),
(5057318, 737921, 64670, '<td valign="top">Clever, clever, clever!</td>', 'Clever, clever, clever!', '2008-11-11 15:38:39.000000', NULL, 1),
(5057326, 737913, 6667, '<td valign="top">I would be very surprised if the pencil were lead filled. . . graphite, yes.</td>', 'I would be very surprised if the pencil were lead filled. . . graphite, yes.', '2008-11-11 15:42:20.000000', NULL, 1),
(5057328, 737375, 6667, '<td valign="top">Clever, very clever!</td>', 'Clever, very clever!', '2008-11-11 15:43:25.000000', NULL, 1),
(5057340, 737824, 45475, '<td valign="top">Hi Jessy. I think this is a great concept. You had a cool idea and were able to make it work with professional flair. Not many of us can pull of beautiful portrait lighting as you''ve done here. Heh, you''ve made science look sexy and glamorous! A 9 from me and for what it''s worth, I think you''re getting robbed on your score....</td>', 'Hi Jessy. I think this is a great concept. You had a cool idea and were able to make it work with professional flair. Not many of us can pull of beautiful portrait lighting as you''ve done here. Heh, you''ve made science look sexy and glamorous! A 9 from me and for what it''s worth, I think you''re getting robbed on your score....', '2008-11-11 15:49:26.000000', NULL, 1),
(5057341, 737787, 52472, '<td valign="top">It''s a bit unfair to bring such a great landscape into this challenge... this accounts for the crooked title. Otherwise it''s a fantastic picture of course, I love your processing.</td>', 'It''s a bit unfair to bring such a great landscape into this challenge... this accounts for the crooked title. Otherwise it''s a fantastic picture of course, I love your processing.', '2008-11-11 15:49:59.000000', NULL, 1),
(5057420, 738224, 18655, '<td valign="top">Great curves. Not sure what it is so looks somewhat abstract to me.</td>', 'Great curves. Not sure what it is so looks somewhat abstract to me.', '2008-11-11 16:18:14.000000', NULL, 1),
(5057431, 737752, 18655, '<td valign="top">sharp - fitting title. Nice bokeh on the winchester</td>', 'sharp - fitting title. Nice bokeh on the winchester', '2008-11-11 16:19:55.000000', NULL, 1),
(5057440, 737741, 18655, '<td valign="top">I like how you used diagonal lines here but don''t care too much for the overall picture since it to me does not have much photographic value</td>', 'I like how you used diagonal lines here but don''t care too much for the overall picture since it to me does not have much photographic value', '2008-11-11 16:21:14.000000', NULL, 1),
(5057449, 737828, 18655, '<td valign="top">Good lighting of an otherwise uninteresting object.</td>', 'Good lighting of an otherwise uninteresting object.', '2008-11-11 16:22:55.000000', NULL, 1),
(5057458, 736929, 18655, '<td valign="top">OK scenic shot. Does not convey the elements to me and the shade on the left doesn''t help.</td>', 'OK scenic shot. Does not convey the elements to me and the shade on the left doesn''t help.', '2008-11-11 16:24:47.000000', NULL, 1),
(5057464, 737821, 18655, '<td valign="top">Nice setup. Looks good with the white background</td>', 'Nice setup. Looks good with the white background', '2008-11-11 16:26:14.000000', NULL, 1),
(5057492, 737869, 18655, '<td valign="top">Background has a dirty color which to me is not attractive and I would have closed the aperture one or two stops to eliminate the blurred "in God we trust".</td>', 'Background has a dirty color which to me is not attractive and I would have closed the aperture one or two stops to eliminate the blurred "in God we trust".', '2008-11-11 16:33:23.000000', NULL, 1),
(5057506, 737946, 18655, '<td valign="top">A little messy with all the flame ''paths'' but looks sharp.</td>', 'A little messy with all the flame ''paths'' but looks sharp.', '2008-11-11 16:37:40.000000', NULL, 1),
(5057508, 737927, 18655, '<td valign="top">I don''t really get it - sorry... looks like some aluminum wrapped around the glass but not sure what the idea is other than include something from the elements.</td>', 'I don''t really get it - sorry... looks like some aluminum wrapped around the glass but not sure what the idea is other than include something from the elements.', '2008-11-11 16:39:01.000000', NULL, 1),
(5057510, 737784, 68947, '<td valign="top">Really nicely done.  Love the crystal plate on top of the server plate.  Adds so nicely to the shot and how the vitamin is sort of "framed" by the medalion like design below.  Nice composition and done really nicely for a plain vitamin!  Good going!</td>', 'Really nicely done.  Love the crystal plate on top of the server plate.  Adds so nicely to the shot and how the vitamin is sort of "framed" by the medalion like design below.  Nice composition and done really nicely for a plain vitamin!  Good going!', '2008-11-11 16:39:24.000000', NULL, 1),
(5057511, 737858, 68947, '<td valign="top">Nice idea.  Must have taken some time to "sculpt" for this shot.  Nicely photographed as well.</td>', 'Nice idea.  Must have taken some time to "sculpt" for this shot.  Nicely photographed as well.', '2008-11-11 16:39:29.000000', NULL, 1),
(5057512, 737776, 68947, '<td valign="top">LOL....there are some days when that''s what I want to do...only I''d use the toilet.  This was a nicer and more pleasing scene! *wink*  Very nicely photographed too.</td>', 'LOL....there are some days when that''s what I want to do...only I''d use the toilet.  This was a nicer and more pleasing scene! *wink*  Very nicely photographed too.', '2008-11-11 16:39:32.000000', NULL, 1),
(5057513, 738223, 68947, '<td valign="top">Really nice stock shot look to this one.  Will probably do well because of that fact.  Not sure that I like the edges quite so washed out on the sides and the diamond doesn''t have quite the sparkle that may make it more dynamic but, then again, I understand the total difficulty in just photographing jewelry period and it''s reflections.</td>', 'Really nice stock shot look to this one.  Will probably do well because of that fact.  Not sure that I like the edges quite so washed out on the sides and the diamond doesn''t have quite the sparkle that may make it more dynamic but, then again, I understand the total difficulty in just photographing jewelry period and it''s reflections.', '2008-11-11 16:39:36.000000', NULL, 1),
(5057514, 737849, 68947, '<td valign="top">Cute concept!  Is that the moon out just below the beam there?  Certainly it meets the challenge and cute title.</td>', 'Cute concept!  Is that the moon out just below the beam there?  Certainly it meets the challenge and cute title.', '2008-11-11 16:39:39.000000', NULL, 1),
(5057516, 737785, 68947, '<td valign="top">Nice shot.  Could have gone into the smoke challenge...or, was this an outtake from it?  Nicely done!</td>', 'Nice shot.  Could have gone into the smoke challenge...or, was this an outtake from it?  Nicely done!', '2008-11-11 16:39:47.000000', NULL, 1),
(5057517, 738147, 68947, '<td valign="top">Very pretty, stock shot style shot.  Nicely done.  Should do well in here.  Just doesn''t really say anything to me though beyond it being a great technical and a lovely piece of jewelry.</td>', 'Very pretty, stock shot style shot.  Nicely done.  Should do well in here.  Just doesn''t really say anything to me though beyond it being a great technical and a lovely piece of jewelry.', '2008-11-11 16:39:50.000000', NULL, 1),
(5057518, 737596, 68947, '<td valign="top">Great capture!  Did you break a thermometer to get the mercury out?  I hope you disposed of it properly???  Sorry, that''s the environmentalist and the safety concern coming out here! *smile*  Nice stock shot style and look...very clear and well focused.</td>', 'Great capture!  Did you break a thermometer to get the mercury out?  I hope you disposed of it properly???  Sorry, that''s the environmentalist and the safety concern coming out here! *smile*  Nice stock shot style and look...very clear and well focused.', '2008-11-11 16:39:53.000000', NULL, 1),
(5057519, 738130, 18655, '<td valign="top">I understand what it is and colors turned out ok but would not have put this picture on my wall.</td>', 'I understand what it is and colors turned out ok but would not have put this picture on my wall.', '2008-11-11 16:39:55.000000', NULL, 1),
(5057520, 737855, 68947, '<td valign="top">Wow...to have that many!  It''s so difficult to get a shot like this, isn''t it?</td>', 'Wow...to have that many!  It''s so difficult to get a shot like this, isn''t it?', '2008-11-11 16:39:58.000000', NULL, 1),
(5057521, 737775, 68947, '<td valign="top">Nicely photographed and interesting coin...great macro shot!</td>', 'Nicely photographed and interesting coin...great macro shot!', '2008-11-11 16:40:01.000000', NULL, 1),
(5057522, 737975, 68947, '<td valign="top">absolutely beautifully shot and lovely composition and colours.  Just a bit of a "shoehorn", right?  A "mirror challenge" outtake, perhaps? *smile*</td>', 'absolutely beautifully shot and lovely composition and colours.  Just a bit of a "shoehorn", right?  A "mirror challenge" outtake, perhaps? *smile*', '2008-11-11 16:40:04.000000', NULL, 1),
(5057523, 737774, 68947, '<td valign="top">Well, what can I say here?  It''s a challenge fitter, but, can''t say much about the "depth" of meaning to this shot. *smile*  I thinketh that you may be a bit fed up or just didn''t have any other ideas????  *smile*</td>', 'Well, what can I say here?  It''s a challenge fitter, but, can''t say much about the "depth" of meaning to this shot. *smile*  I thinketh that you may be a bit fed up or just didn''t have any other ideas????  *smile*', '2008-11-11 16:40:08.000000', NULL, 1),
(5057527, 738238, 68947, '<td valign="top">Very pretty model, love her eyes....fits the challenge, nice framing and skin tones....the gold just seems a bit out of focus or something???</td>', 'Very pretty model, love her eyes....fits the challenge, nice framing and skin tones....the gold just seems a bit out of focus or something???', '2008-11-11 16:40:28.000000', NULL, 1),
(5057528, 737787, 68947, '<td valign="top">Really nice setting for this and the colour standing out from the background works well.  Just not sure that I''m a big fan of all of the blurring.  Perhaps, having left the foreground in focus and having blurred out the background as you have it might have been better, but others will likely agree with this amount of blur to it.</td>', 'Really nice setting for this and the colour standing out from the background works well.  Just not sure that I''m a big fan of all of the blurring.  Perhaps, having left the foreground in focus and having blurred out the background as you have it might have been better, but others will likely agree with this amount of blur to it.', '2008-11-11 16:40:33.000000', NULL, 1),
(5057529, 737927, 68947, '<td valign="top">Interesting shot...hmmmm....I know it''s difficult to photograph glass effectively but the background items are distracting.  Would have worked well against a purely back/dark background.</td>', 'Interesting shot...hmmmm....I know it''s difficult to photograph glass effectively but the background items are distracting.  Would have worked well against a purely back/dark background.', '2008-11-11 16:40:36.000000', NULL, 1),
(5057530, 737882, 68947, '<td valign="top">Cute.  I get where you were going with the background but, it seems "half done" which kind of makes me look more at the blurring of the background than the actual items.  Still, a really nice shot and message!</td>', 'Cute.  I get where you were going with the background but, it seems "half done" which kind of makes me look more at the blurring of the background than the actual items.  Still, a really nice shot and message!', '2008-11-11 16:40:45.000000', NULL, 1),
(5057531, 737769, 68947, '<td valign="top">Nicely done.  Love the contrast and the DOF and focus on this.</td>', 'Nicely done.  Love the contrast and the DOF and focus on this.', '2008-11-11 16:40:49.000000', NULL, 1),
(5057533, 737587, 68947, '<td valign="top">LOL...makes a statement.....finances stood on their heads! *grin*</td>', 'LOL...makes a statement.....finances stood on their heads! *grin*', '2008-11-11 16:40:52.000000', NULL, 1),
(5057535, 737990, 68947, '<td valign="top">Well, artsy shot...bright and crisp but, not sure what else to say about it???  It fits the challenge, I suppose but a rather flat sort of shot??</td>', 'Well, artsy shot...bright and crisp but, not sure what else to say about it???  It fits the challenge, I suppose but a rather flat sort of shot??', '2008-11-11 16:40:57.000000', NULL, 1),
(5057536, 738130, 68947, '<td valign="top">Ok, I can see that this is what it is, but I think that asking why I would want a shot of just this, is likely a question that I''d want to ask. *smile*  I know that this should be an artsy shot.....but, given the nature of this site, I''m sure that you know or knew that it wouldn''t do well in here.  A perhaps, statement that you''re making here with this one? *smile*</td>', 'Ok, I can see that this is what it is, but I think that asking why I would want a shot of just this, is likely a question that I''d want to ask. *smile*  I know that this should be an artsy shot.....but, given the nature of this site, I''m sure that you know or knew that it wouldn''t do well in here.  A perhaps, statement that you''re making here with this one? *smile*', '2008-11-11 16:41:00.000000', NULL, 1),
(5057537, 737235, 68947, '<td valign="top">Well, that''s a very different approach and well executed! Kind of gets that "stock shot", "pretty" look that is loved so well in here but, fits the challenge.  Nicely done!</td>', 'Well, that''s a very different approach and well executed! Kind of gets that "stock shot", "pretty" look that is loved so well in here but, fits the challenge.  Nicely done!', '2008-11-11 16:41:02.000000', NULL, 1),
(5057538, 737869, 68947, '<td valign="top">Who knew a penny could look so pretty?  Nicely done.</td>', 'Who knew a penny could look so pretty?  Nicely done.', '2008-11-11 16:41:11.000000', NULL, 1),
(5057539, 737922, 68947, '<td valign="top">LOL...ok, I like the idea behind this shot.  It''s kind of like the paper curls only in metal.  Very creative!</td>', 'LOL...ok, I like the idea behind this shot.  It''s kind of like the paper curls only in metal.  Very creative!', '2008-11-11 16:41:14.000000', NULL, 1),
(5057540, 737857, 68947, '<td valign="top">Or, Sunrisia/Sunsetia?  LOL</td>', 'Or, Sunrisia/Sunsetia?  LOL', '2008-11-11 16:41:19.000000', NULL, 1),
(5057541, 737919, 68947, '<td valign="top">Very cute!  You pulled that off really nicely!  Like it!</td>', 'Very cute!  You pulled that off really nicely!  Like it!', '2008-11-11 16:41:23.000000', NULL, 1),
(5057544, 737572, 68947, '<td valign="top">Not sure on what to say here.  It just doesn''t quite do it for me and I can''t tell you why, except...perhaps, the composition with the other details around it??  I don''t know why I''m trying to comment because I can''t put it into words but, perhaps, "I don''t get it" may come closest rather than, "boring"???  Sorry.  Don''t mean to be so cruel sounding.  I really don''t.  Just don''t know how else to say it and figure that saying nothing is not great either???  Ok, shutting up now. :)</td>', 'Not sure on what to say here.  It just doesn''t quite do it for me and I can''t tell you why, except...perhaps, the composition with the other details around it??  I don''t know why I''m trying to comment because I can''t put it into words but, perhaps, "I don''t get it" may come closest rather than, "boring"???  Sorry.  Don''t mean to be so cruel sounding.  I really don''t.  Just don''t know how else to say it and figure that saying nothing is not great either???  Ok, shutting up now. :)', '2008-11-11 16:41:35.000000', NULL, 1),
(5057546, 738142, 68947, '<td valign="top">Well, interesting use and composition!  LOL</td>', 'Well, interesting use and composition!  LOL', '2008-11-11 16:41:43.000000', NULL, 1),
(5057547, 737811, 68947, '<td valign="top">Very abstract, lovely colours and without the title, I''d not have a clue in heck what this was! *grin*</td>', 'Very abstract, lovely colours and without the title, I''d not have a clue in heck what this was! *grin*', '2008-11-11 16:41:46.000000', NULL, 1),
(5057548, 737791, 68947, '<td valign="top">Comes right at ya! *smile*  Very nice compostion and DOF.</td>', 'Comes right at ya! *smile*  Very nice compostion and DOF.', '2008-11-11 16:41:50.000000', NULL, 1),
(5057549, 737505, 68947, '<td valign="top">Lovely macro, very clear, fits challenge.</td>', 'Lovely macro, very clear, fits challenge.', '2008-11-11 16:41:53.000000', NULL, 1),
(5057550, 737862, 68947, '<td valign="top">CUTE!  Lighting seems a bit off or overprocessed??  Still, made me smile!</td>', 'CUTE!  Lighting seems a bit off or overprocessed??  Still, made me smile!', '2008-11-11 16:41:56.000000', NULL, 1),
(5057551, 737780, 68947, '<td valign="top">Lovely shot but, focus seems a bit off</td>', 'Lovely shot but, focus seems a bit off', '2008-11-11 16:41:58.000000', NULL, 1),
(5057552, 737873, 68947, '<td valign="top">Composition is nice, interesting subject but, something is lacking.  Just don''t know what?</td>', 'Composition is nice, interesting subject but, something is lacking.  Just don''t know what?', '2008-11-11 16:42:01.000000', NULL, 1),
(5057553, 737830, 68947, '<td valign="top">Nice stock shot look to this and I''m sure it will do ok but, hasn''t much pizazz...perhaps, having a hand below it might have added to it?  I DO get the message behind the falling gold prices though!</td>', 'Nice stock shot look to this and I''m sure it will do ok but, hasn''t much pizazz...perhaps, having a hand below it might have added to it?  I DO get the message behind the falling gold prices though!', '2008-11-11 16:42:04.000000', NULL, 1),
(5057554, 737523, 68947, '<td valign="top">Lovely macro</td>', 'Lovely macro', '2008-11-11 16:42:07.000000', NULL, 1),
