(5057753, 737765, 36382, '<td valign="top">I could see this on the front of a greetings card.</td>', 'I could see this on the front of a greetings card.', '2008-11-11 17:48:07.000000', NULL, 1),
(5057759, 738039, 18655, '<td valign="top">A pticture of money... If you could only use that money towards a book explaining wha constitutes photographic value it would maybe do some good.<br/> <br/>Very sharp though and good lighting.</td>', 'A pticture of money... If you could only use that money towards a book explaining wha constitutes photographic value it would maybe do some good. Very sharp though and good lighting.', '2008-11-11 17:50:16.000000', NULL, 1),
(5057761, 737587, 18655, '<td valign="top">Another coin - yawn... not very creative and doesn''t really convey the elements to me although it was made of silver</td>', 'Another coin - yawn... not very creative and doesn''t really convey the elements to me although it was made of silver', '2008-11-11 17:51:31.000000', NULL, 1),
(5057763, 738091, 18655, '<td valign="top">I see that it is copper but just not a very attractive photography that I wuld have had on my wall</td>', 'I see that it is copper but just not a very attractive photography that I wuld have had on my wall', '2008-11-11 17:52:15.000000', NULL, 1),
