(5057787, 737838, 18655, '<td valign="top">I like it but I''m also plane crazy... :)</td>', 'I like it but I''m also plane crazy... :)', '2008-11-11 18:04:54.000000', NULL, 1),
(5057788, 737785, 3087, '<td valign="top">I like the blocks of colour - lime green, orange, white, blue and purple.</td>', 'I like the blocks of colour - lime green, orange, white, blue and purple.', '2008-11-11 18:04:59.000000', NULL, 1),
(5057789, 737874, 3087, '<td valign="top">Oooh this is lovely. Not only a great composition (the way the weight sits so heavily on one side against that one slender coil creates quite a tension, for me) but also beautifully sharp and with such a lovely shallow DOF. Mmmmm!</td>', 'Oooh this is lovely. Not only a great composition (the way the weight sits so heavily on one side against that one slender coil creates quite a tension, for me) but also beautifully sharp and with such a lovely shallow DOF. Mmmmm!', '2008-11-11 18:05:43.000000', NULL, 1),
(5057792, 738147, 18655, '<td valign="top">Not a bad attempt. Not sure about the frame but I love the minimalistic look</td>', 'Not a bad attempt. Not sure about the frame but I love the minimalistic look', '2008-11-11 18:06:10.000000', NULL, 1),
(5057793, 737899, 18655, '<td valign="top">Too messy. No photographic value...</td>', 'Too messy. No photographic value...', '2008-11-11 18:06:39.000000', NULL, 1),
(5057795, 737830, 18655, '<td valign="top">I see that - but just not a very attractive image.</td>', 'I see that - but just not a very attractive image.', '2008-11-11 18:07:21.000000', NULL, 1),
(5057796, 737844, 18655, '<td valign="top">A little busy but a good idea</td>', 'A little busy but a good idea', '2008-11-11 18:07:40.000000', NULL, 1),
(5057798, 737990, 3087, '<td valign="top">Strong geometry and lovely textures too. Nice use of light, shadow and form.</td>', 'Strong geometry and lovely textures too. Nice use of light, shadow and form.', '2008-11-11 18:10:46.000000', NULL, 1),
(5057800, 737929, 3087, '<td valign="top">That''s wonderful, really like it. Very ethereal.</td>', 'That''s wonderful, really like it. Very ethereal.', '2008-11-11 18:11:09.000000', NULL, 1),
(5057801, 738133, 3087, '<td valign="top">Ha, nice pun! :)</td>', 'Ha, nice pun! :)', '2008-11-11 18:11:25.000000', NULL, 1),
(5057803, 737787, 3087, '<td valign="top">I''m not sure about the processing, it''s got some strange soft focus that I''m not keen on and it''s also making the boy seem superimposed, which I''m sure he''s not! But the image itself, I like very much, especially the colour contrast between the blue in the balloons and clothing and the browns, oranges and yellows of the forest.</td>', 'I''m not sure about the processing, it''s got some strange soft focus that I''m not keen on and it''s also making the boy seem superimposed, which I''m sure he''s not! But the image itself, I like very much, especially the colour contrast between the blue in the balloons and clothing and the browns, oranges and yellows of the forest.', '2008-11-11 18:12:40.000000', NULL, 1),
(5057804, 737819, 3087, '<td valign="top">That''s clever and nicely executed too...</td>', 'That''s clever and nicely executed too...', '2008-11-11 18:13:29.000000', NULL, 1),
(5057805, 737100, 3087, '<td valign="top">Simple but lovely. Great composition.</td>', 'Simple but lovely. Great composition.', '2008-11-11 18:13:46.000000', NULL, 1),
(5057807, 737908, 3087, '<td valign="top">Fantastic texture and sharpness of detail, great tight-in composition, nice use of shallow DOF, lovely contrasty black and white. ALL GOOD!</td>', 'Fantastic texture and sharpness of detail, great tight-in composition, nice use of shallow DOF, lovely contrasty black and white. ALL GOOD!', '2008-11-11 18:14:27.000000', NULL, 1),
(5057811, 738238, 18197, '<td valign="top">Too much smoothing for my taste. Otherwise a lovely model and image. If natural, it''s probably a curse to have skin this perfect.</td>', 'Too much smoothing for my taste. Otherwise a lovely model and image. If natural, it''s probably a curse to have skin this perfect.', '2008-11-11 18:19:50.000000', NULL, 1),
(5057821, 737596, 97225, '<td valign="top">Beautiful - simple and clean.</td>', 'Beautiful - simple and clean.', '2008-11-11 18:38:42.000000', NULL, 1),
(5057823, 737914, 97225, '<td valign="top">Nicely exposed.</td>', 'Nicely exposed.', '2008-11-11 18:39:21.000000', NULL, 1),
