INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5057880, 737892, 90678, '<td valign="top">The texture makes it almost look like a macro shot of fried chicken.  I wonder if a contrasting background would help to set this in context.</td>', 'The texture makes it almost look like a macro shot of fried chicken.  I wonder if a contrasting background would help to set this in context.', '2008-11-11 19:22:50.000000', NULL, 1),
(5057882, 737914, 90678, '<td valign="top">Creative idea, I like the composition.</td>', 'Creative idea, I like the composition.', '2008-11-11 19:24:35.000000', NULL, 1),
(5057886, 737485, 90678, '<td valign="top">Wow, the image creates a weird optical effect where the periodic table jumps behind the ingot.</td>', 'Wow, the image creates a weird optical effect where the periodic table jumps behind the ingot.', '2008-11-11 19:26:12.000000', NULL, 1),
(5057888, 737908, 90678, '<td valign="top">Great image, I love the DOF and the detail.</td>', 'Great image, I love the DOF and the detail.', '2008-11-11 19:28:00.000000', NULL, 1),
(5057892, 737975, 90678, '<td valign="top">Nice approach, but I find the shadow on the flower distracting.  The image also seems about a stop under exposed.</td>', 'Nice approach, but I find the shadow on the flower distracting.  The image also seems about a stop under exposed.', '2008-11-11 19:29:52.000000', NULL, 1),
(5057895, 737899, 90678, '<td valign="top">Neat image, is that a copper scouring pad?</td>', 'Neat image, is that a copper scouring pad?', '2008-11-11 19:32:34.000000', NULL, 1),
(5057900, 737821, 90678, '<td valign="top">Now theres something you dont see every dayGreat capture I hope it doesnt get voted down as DNMC.</td>', 'Now theres something you dont see every dayGreat capture I hope it doesnt get voted down as DNMC.', '2008-11-11 19:38:51.000000', NULL, 1),
(5057901, 737932, 90678, '<td valign="top">The face is so reflective, to me, it makes the whole image feel soft.</td>', 'The face is so reflective, to me, it makes the whole image feel soft.', '2008-11-11 19:38:57.000000', NULL, 1),
(5057903, 737941, 90678, '<td valign="top">Great composition and use of color.</td>', 'Great composition and use of color.', '2008-11-11 19:39:45.000000', NULL, 1),
(5057906, 737929, 90678, '<td valign="top">The slight blur really gives it that ''dreamy'' feeling.</td>', 'The slight blur really gives it that ''dreamy'' feeling.', '2008-11-11 19:40:40.000000', NULL, 1),
(5057908, 737822, 90678, '<td valign="top">Interesting image, but I just can''t seem to figure out what it is.</td>', 'Interesting image, but I just can''t seem to figure out what it is.', '2008-11-11 19:43:12.000000', NULL, 1),
(5057912, 737819, 17203, '<td valign="top">Awesome job- you absolutely nailed the challenge. The background chart is a little crooked, but otherwise a perfect entry, and my pick for the blue! 10</td>', 'Awesome job- you absolutely nailed the challenge. The background chart is a little crooked, but otherwise a perfect entry, and my pick for the blue! 10', '2008-11-11 19:53:27.000000', NULL, 1),
(5057913, 737812, 17203, '<td valign="top">A very strong image with great color and composition, but your score will probably get hit for DNMC since mercury is silver (this is tinted alcohol).</td>', 'A very strong image with great color and composition, but your score will probably get hit for DNMC since mercury is silver (this is tinted alcohol).', '2008-11-11 19:57:08.000000', NULL, 1),
(5057924, 737964, 17203, '<td valign="top">Um... it''s a rock. OK, I understand it may be iron ore, but you didn''t DO anything with it to make a visual connection with "element." Maybe carve an "Fe" symbol into the surface or put a puff of smoke behind it and call it a steam iron. Something, <i>anything</i> to make an interesting story. As-is, every single voter will look at this and think, "It''s just a rock."  :-(</td>', 'Um... it''s a rock. OK, I understand it may be iron ore, but you didn''t DO anything with it to make a visual connection with "element." Maybe carve an "Fe" symbol into the surface or put a puff of smoke behind it and call it a steam iron. Something, anything to make an interesting story. As-is, every single voter will look at this and think, "It''s just a rock."  :-(', '2008-11-11 20:10:23.000000', NULL, 1),
(5057935, 738110, 17203, '<td valign="top">Great subject, not so great light. Dramatic lighting would have made a HUGE difference on this one and helped define the crystalline structure.</td>', 'Great subject, not so great light. Dramatic lighting would have made a HUGE difference on this one and helped define the crystalline structure.', '2008-11-11 20:32:20.000000', NULL, 1),
(5057943, 736675, 66616, '<td valign="top">nice image</td>', 'nice image', '2008-11-11 20:38:22.000000', NULL, 1),
(5057945, 737666, 66616, '<td valign="top">great idea, perhaps more dof would improve this.</td>', 'great idea, perhaps more dof would improve this.', '2008-11-11 20:39:43.000000', NULL, 1),
(5057947, 737862, 66616, '<td valign="top">thats NaCl isnt it?</td>', 'thats NaCl isnt it?', '2008-11-11 20:40:50.000000', NULL, 1),
(5057955, 736929, 66616, '<td valign="top">80% N 16% O</td>', '80% N 16% O', '2008-11-11 20:45:19.000000', NULL, 1),
(5057956, 737858, 66616, '<td valign="top">great idea</td>', 'great idea', '2008-11-11 20:45:37.000000', NULL, 1),
(5057960, 737787, 66616, '<td valign="top">nice shot</td>', 'nice shot', '2008-11-11 20:48:39.000000', NULL, 1),
(5057968, 737913, 66616, '<td valign="top">its actually a clay and graphite mixture.</td>', 'its actually a clay and graphite mixture.', '2008-11-11 20:51:56.000000', NULL, 1),
(5057969, 737914, 66616, '<td valign="top">They actually use different elements like mercury to get the different colours.</td>', 'They actually use different elements like mercury to get the different colours.', '2008-11-11 20:52:44.000000', NULL, 1),
(5057987, 737882, 96915, '<td valign="top">There''s quite a bit of noise and halos around the rings.  Not sure whether either was intentional, but to me it distracts from the image.</td>', 'There''s quite a bit of noise and halos around the rings.  Not sure whether either was intentional, but to me it distracts from the image.', '2008-11-11 21:01:45.000000', NULL, 1),
(5057991, 737886, 96915, '<td valign="top">I would have liked this more if the diamonds had more clarity.  For some reason, and maybe it''s the cut or the lighting, they look chipped or not very clean.  Also, I''d like to see the diamond in the foreground with better focus.</td>', 'I would have liked this more if the diamonds had more clarity.  For some reason, and maybe it''s the cut or the lighting, they look chipped or not very clean.  Also, I''d like to see the diamond in the foreground with better focus.', '2008-11-11 21:03:34.000000', NULL, 1),
(5057992, 737843, 96915, '<td valign="top">I''d like to see this with either more or less of her hand in the frame.  As it is with the tips amputated, the crop just doesn''t seem right.  I do like the processing to make the ring stand out from everything else in the image.</td>', 'I''d like to see this with either more or less of her hand in the frame.  As it is with the tips amputated, the crop just doesn''t seem right.  I do like the processing to make the ring stand out from everything else in the image.', '2008-11-11 21:05:39.000000', NULL, 1),
(5058006, 737858, 17850, '<td valign="top">Great idea, the best image in this challenge! (10)</td>', 'Great idea, the best image in this challenge! (10)', '2008-11-11 21:15:57.000000', NULL, 1),
(5058018, 737671, 88136, '<td valign="top">ah this is always a fun experiment, my uncle does it all the time:) i love the bubbles and the wonderful blue background. looks great</td>', 'ah this is always a fun experiment, my uncle does it all the time:) i love the bubbles and the wonderful blue background. looks great', '2008-11-11 21:24:33.000000', NULL, 1),
(5058020, 737869, 88136, '<td valign="top">i like the reflection. nice and shiny penny too</td>', 'i like the reflection. nice and shiny penny too', '2008-11-11 21:26:14.000000', NULL, 1),
(5058022, 737812, 88136, '<td valign="top">oh nice! i like it. where do you live?! its winter!! (here at least:)-8</td>', 'oh nice! i like it. where do you live?! its winter!! (here at least:)-8', '2008-11-11 21:29:30.000000', NULL, 1),
(5058025, 736675, 88136, '<td valign="top">very cool. i wish my telescope would cooperate and let me take pics like this. i do like it, very out-of-this-world:)</td>', 'very cool. i wish my telescope would cooperate and let me take pics like this. i do like it, very out-of-this-world:)', '2008-11-11 21:30:43.000000', NULL, 1),
(5058027, 737820, 88136, '<td valign="top">well the building in the background is distracting. interesting idea though</td>', 'well the building in the background is distracting. interesting idea though', '2008-11-11 21:31:25.000000', NULL, 1),
(5058028, 738225, 88136, '<td valign="top">i like you take on this challenge.  too tight of crop though</td>', 'i like you take on this challenge.  too tight of crop though', '2008-11-11 21:32:49.000000', NULL, 1),
(5058034, 737596, 88136, '<td valign="top">very cool. great take on the challenge. very beautiful. i bet it scores very high-10</td>', 'very cool. great take on the challenge. very beautiful. i bet it scores very high-10', '2008-11-11 21:36:24.000000', NULL, 1),
(5058069, 737913, 30490, '<td valign="top">Actually graphite... but a neat image anyway.</td>', 'Actually graphite... but a neat image anyway.', '2008-11-11 21:48:56.000000', NULL, 1),
(5058090, 737892, 30490, '<td valign="top">I think the lighting of this image could be improved.  It is too harsh and doesn''t give you enough definition to the subject.  The depth of field is off too.  It ends up looking like a massive lump of cheddar cheese rather than sulfur.</td>', 'I think the lighting of this image could be improved.  It is too harsh and doesn''t give you enough definition to the subject.  The depth of field is off too.  It ends up looking like a massive lump of cheddar cheese rather than sulfur.', '2008-11-11 22:02:07.000000', NULL, 1),
(5058092, 738254, 30490, '<td valign="top">The lighting isn''t working for me on this image.  The single bright spot is distracting and the background looks like chocolate.  I won''t be surprised if it get''s DQ''ed for the writing in the lower left corner too.  Better luck next time.</td>', 'The lighting isn''t working for me on this image.  The single bright spot is distracting and the background looks like chocolate.  I won''t be surprised if it get''s DQ''ed for the writing in the lower left corner too.  Better luck next time.', '2008-11-11 22:03:40.000000', NULL, 1),
(5058094, 737791, 30490, '<td valign="top">Great idea, just not quite there execution wise.  The close up means that you lose the focus as the "spokes" exit the frame.  This is very distracting and moves the viewer''s eye around the image too much.  I love the background color and the way the twisted metal was light though.  Better luck next time.</td>', 'Great idea, just not quite there execution wise.  The close up means that you lose the focus as the "spokes" exit the frame.  This is very distracting and moves the viewer''s eye around the image too much.  I love the background color and the way the twisted metal was light though.  Better luck next time.', '2008-11-11 22:05:36.000000', NULL, 1),
(5058096, 737820, 30490, '<td valign="top">The colors seem "off" to me and the image appears "flat".  It may be my monitor, but overall this image just isn''t hitting it out of the ball park for me.  Maybe it is the small amount of iron compared to the overall image.  Seems kind of like a "shoe horn" image.  You had it and found a way to "fit it into" this challenge.  Best of luck to you.</td>', 'The colors seem "off" to me and the image appears "flat".  It may be my monitor, but overall this image just isn''t hitting it out of the ball park for me.  Maybe it is the small amount of iron compared to the overall image.  Seems kind of like a "shoe horn" image.  You had it and found a way to "fit it into" this challenge.  Best of luck to you.', '2008-11-11 22:07:34.000000', NULL, 1),
(5058097, 737913, 60505, '<td valign="top">graphite (Carbon) actually.</td>', 'graphite (Carbon) actually.', '2008-11-11 22:07:38.000000', NULL, 1),
(5058098, 737867, 60505, '<td valign="top">2 elements, as a compound</td>', '2 elements, as a compound', '2008-11-11 22:08:13.000000', NULL, 1),
(5058099, 737814, 2389, '<td valign="top">Very clever and well done - love the lighting effect! -10=</td>', 'Very clever and well done - love the lighting effect! -10=', '2008-11-11 22:08:54.000000', NULL, 1),
(5058101, 737857, 30490, '<td valign="top">Ok, maybe I lack creativity, but I just don''t like made up elements when there are so many real one''s to choose from.  Besides that, the image isn''t very interesting and isn''t very well executed.  Maybe going for the brown award here?</td>', 'Ok, maybe I lack creativity, but I just don''t like made up elements when there are so many real one''s to choose from.  Besides that, the image isn''t very interesting and isn''t very well executed.  Maybe going for the brown award here?', '2008-11-11 22:09:11.000000', NULL, 1),
